/* ============================================================
   words.js — 全局单词库（英 → 中）
   ------------------------------------------------------------
   格式：  "词条": "中文释义|词性|音标"
   - 释义多义项用中文分号「；」分隔，第一项是最常用义
   - 词性、音标可省略：  "词条": "中文释义"
   - key 一律小写；缩略形式（can't / I'm / that's）单独收录
   - 覆盖原则：剧集台词里出现的每一个词形都必须在这里查到
     用 tools/check-coverage.js 校验，必须 100%
   ------------------------------------------------------------
   注意：这里的释义是「通用义」。如果某个词在某句里是特殊含义，
   在该句的 words 字段里覆盖（见 README「逐词精译」）。
   ============================================================ */

